var i=`0272-jota`;var n=`world-0272`;var a=`SI`;var o=`southern-europe`;var r=4;var s=853;var l={en:`Jota`,ua:`Йота`};var d={en:`A traditional Slovenia dish made with dry white beans, potato, bay leaf, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Словенія. Основні інгредієнти: суха біла квасоля, картопля, лавровий лист, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Cover the ingredients with cold water and soak for about 720 minutes; keep fish in the refrigerator, refreshing the water several times to remove excess salt. Drain before cooking.`,ua:`Залийте складники холодною водою і замочуйте приблизно 720 хвилин; рибу тримайте в холодильнику, кілька разів змінюючи воду для видалення зайвої солі. Перед готуванням злийте воду.`,t:[`soaking-legumes`],m:720,i:[[`dry-white-beans`,300,`g`],[`water`,1100,`ml`]]},{en:`Drain the soaked beans and cook them in fresh water until nearly tender, about 75 minutes.`,ua:`Злийте воду із замоченої квасолі й варіть її у свіжій воді приблизно 75 хвилин майже до м’якості.`,t:[`boiling`],m:75,i:[]},{en:`Add diced potatoes and bay leaves to the simmering beans; cook for 15 minutes until tender.`,ua:`Додайте до квасолі нарізану картоплю та лавровий лист, варіть ще 15 хвилин до м’якості.`,t:[`boiling`],m:15,i:[[`potato`,370,`g`],[`bay-leaf`,2,`leaf`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,160,`g`],[`garlic`,4,`clove`],[`extra-virgin-olive-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`sauerkraut`,380,`g`],[`smoked-ham`,230,`g`],[`table-salt`,null,`to_taste`]]}];var g={slug:i,id:n,country:`SI`,region:o,servings:4,minutes:853,title:l,text:d,steps:u};export{a as country,g as default,n as id,s as minutes,o as region,r as servings,i as slug,u as steps,d as text,l as title};